-- Repairs 36 of 79 CHECK constraints and 3 partial indexes that muster_007 and
-- muster_009 got wrong. Every one of them dropped allowed values.
--
-- This was invisible to the earlier verification because that verification
-- counted objects (79 checks, 122 indexes) instead of comparing their
-- definitions. Counting proves nothing about content. It surfaced only when
-- real data hit the constraints: muster.users row 3 (the super_admin) was
-- rejected because users_role_check here permitted only 'user' and 'admin'.
--
-- Every structural object type is now compared by md5 of its definition, not
-- by count. Columns, primary keys, unique constraints and foreign keys already
-- matched on that basis; these two did not.
alter table muster.agents drop constraint if exists agents_kind_check; alter table muster.agents add constraint agents_kind_check CHECK (((kind)::text = ANY ((ARRAY['internal_employee'::character varying, 'customer_agent'::character varying, 'integration'::character varying])::text[])));
alter table muster.brand_profiles drop constraint if exists brand_profiles_client_price_cadence_check; alter table muster.brand_profiles add constraint brand_profiles_client_price_cadence_check CHECK (((client_price_cadence IS NULL) OR ((client_price_cadence)::text = ANY ((ARRAY['monthly'::character varying, 'annual'::character varying, 'one_time'::character varying, 'custom'::character varying])::text[]))));
alter table muster.brand_profiles drop constraint if exists brand_profiles_tone_check; alter table muster.brand_profiles add constraint brand_profiles_tone_check CHECK (((tone)::text = ANY ((ARRAY['executive'::character varying, 'plain'::character varying, 'technical'::character varying])::text[])));
alter table muster.change_events drop constraint if exists change_events_status_check; alter table muster.change_events add constraint change_events_status_check CHECK (((status)::text = ANY ((ARRAY['open'::character varying, 'reviewed'::character varying, 'ignored'::character varying])::text[])));
alter table muster.commercial_pricing drop constraint if exists commercial_pricing_stage_check; alter table muster.commercial_pricing add constraint commercial_pricing_stage_check CHECK (((stage)::text = ANY ((ARRAY['seed'::character varying, 'fruit'::character varying])::text[])));
alter table muster.commercial_pricing drop constraint if exists commercial_pricing_tier_check; alter table muster.commercial_pricing add constraint commercial_pricing_tier_check CHECK (((tier)::text = ANY ((ARRAY['muster'::character varying, 'muster_partner'::character varying])::text[])));
alter table muster.feature_flags drop constraint if exists feature_flags_scope_check; alter table muster.feature_flags add constraint feature_flags_scope_check CHECK (((scope)::text = ANY ((ARRAY['platform'::character varying, 'organization'::character varying, 'user'::character varying])::text[])));
alter table muster.findings drop constraint if exists findings_confidence_check; alter table muster.findings add constraint findings_confidence_check CHECK (((confidence)::text = ANY ((ARRAY['high'::character varying, 'medium'::character varying, 'low'::character varying])::text[])));
alter table muster.findings drop constraint if exists findings_severity_check; alter table muster.findings add constraint findings_severity_check CHECK (((severity)::text = ANY ((ARRAY['critical'::character varying, 'high'::character varying, 'medium'::character varying, 'low'::character varying, 'info'::character varying])::text[])));
alter table muster.findings drop constraint if exists findings_status_check; alter table muster.findings add constraint findings_status_check CHECK (((status)::text = ANY ((ARRAY['open'::character varying, 'reopened'::character varying, 'resolved'::character varying, 'accepted'::character varying, 'false_positive'::character varying])::text[])));
alter table muster.incidents drop constraint if exists incidents_recovery_result_check; alter table muster.incidents add constraint incidents_recovery_result_check CHECK (((recovery_result)::text = ANY ((ARRAY['recovered'::character varying, 'failed'::character varying, 'not_applicable'::character varying])::text[])));
alter table muster.incidents drop constraint if exists incidents_root_cause_classification_check; alter table muster.incidents add constraint incidents_root_cause_classification_check CHECK (((root_cause_classification)::text = ANY ((ARRAY['expected_validation'::character varying, 'user_misunderstanding'::character varying, 'ux_defect'::character varying, 'permission_denial'::character varying, 'expired_connection'::character varying, 'bad_configuration'::character varying, 'external_outage'::character varying, 'quota_limit'::character varying, 'data_drift'::character varying, 'race_condition'::character varying, 'regression'::character varying, 'code_defect'::character varying, 'security_incident'::character varying, 'unresolved'::character varying])::text[])));
alter table muster.incidents drop constraint if exists incidents_severity_check; alter table muster.incidents add constraint incidents_severity_check CHECK (((severity)::text = ANY ((ARRAY['info'::character varying, 'warning'::character varying, 'critical'::character varying])::text[])));
alter table muster.incidents drop constraint if exists incidents_source_check; alter table muster.incidents add constraint incidents_source_check CHECK (((source)::text = ANY ((ARRAY['cron_failure'::character varying, 'cron_missed'::character varying, 'scan_stuck'::character varying, 'scan_silent_failure'::character varying, 'alert_dead_letter'::character varying, 'commercial_grant_stuck'::character varying, 'engine_error_spike'::character varying, 'manual'::character varying])::text[])));
alter table muster.incidents drop constraint if exists incidents_status_check; alter table muster.incidents add constraint incidents_status_check CHECK (((status)::text = ANY ((ARRAY['open'::character varying, 'investigating'::character varying, 'recovered'::character varying, 'patch_pending'::character varying, 'patch_verified'::character varying, 'awaiting_release'::character varying, 'deployed_awaiting_observation'::character varying, 'closed'::character varying, 'wont_fix'::character varying])::text[])));
