alter table muster.pricing_settings drop constraint if exists pricing_settings_current_stage_check; alter table muster.pricing_settings add constraint pricing_settings_current_stage_check CHECK (((current_stage)::text = ANY ((ARRAY['seed'::character varying, 'fruit'::character varying])::text[])));
