alter table muster.scans drop constraint if exists scans_trigger_check; alter table muster.scans add constraint scans_trigger_check CHECK (((trigger)::text = ANY ((ARRAY['scheduled'::character varying, 'manual'::character varying, 'api'::character varying, 'onboarding'::character varying])::text[])));
